### Objective
Build a production-grade Physics-Based Spring Sheet & Gesture Fling Dismiss Canvas in Flutter. The application demonstrates real-time drag tracking with rubber-band resistance, seamless momentum transfer from DragEndDetails velocity into a SpringSimulation via AnimationController.animateWith(), dynamic damping adjustments (under-damped bounciness vs critically-damped precision), and friction flinging.

```dart
import 'package:flutter/material.dart';
import 'package:flutter/physics.dart';

void main() {
  runApp(const PhysicsMasterclassApp());
}

class PhysicsMasterclassApp extends StatelessWidget {
  const PhysicsMasterclassApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Physics-Based Animations',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorSchemeSeed: Colors.indigo,
        useMaterial3: true,
      ),
      home: const PhysicsPlaygroundScreen(),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. PLAYGROUND PRESENTATION SCREEN
// ─────────────────────────────────────────────────────────────────────────────

class PhysicsPlaygroundScreen extends StatefulWidget {
  const PhysicsPlaygroundScreen({super.key});

  @override
  State<PhysicsPlaygroundScreen> createState() => _PhysicsPlaygroundScreenState();
}

enum SpringPreset {
  bouncy('Playful (Bouncy)', 0.5, 200.0),
  snappy('Critically Damped (Snappy)', 1.0, 350.0),
  stiff('High Stiffness (Tight)', 0.8, 800.0);

  final String label;
  final double dampingRatio;
  final double stiffness;

  const SpringPreset(this.label, this.dampingRatio, this.stiffness);
}

class _PhysicsPlaygroundScreenState extends State<PhysicsPlaygroundScreen>
    with SingleTickerProviderStateMixin {
  late final AnimationController _physicsController;
  late Alignment _dragAlignment;
  late Animation<Alignment> _alignmentAnimation;

  SpringPreset _selectedPreset = SpringPreset.bouncy;
  double _lastVelocity = 0.0;
  bool _isDragging = false;

  @override
  void initState() {
    super.initState();
    _dragAlignment = Alignment.center;
    _physicsController = AnimationController(vsync: this);
    _physicsController.addListener(() {
      setState(() => _dragAlignment = _alignmentAnimation.value);
    });
  }

  @override
  void dispose() {
    _physicsController.dispose();
    super.dispose();
  }

  void _runSpringSimulation(Offset pixelsPerSecond, Size size) {
    _lastVelocity = pixelsPerSecond.distance;

    // 1. Create alignment animation from current position to center
    _alignmentAnimation = _physicsController.drive(
      AlignmentTween(
        begin: _dragAlignment,
        end: Alignment.center,
      ),
    );

    // 2. Convert pixel velocity into alignment coordinate velocity (-1.0 to 1.0)
    // Alignment units: 1.0 unit = half of the width/height
    final unitsPerSecondX = pixelsPerSecond.dx / (size.width / 2);
    final unitsPerSecondY = pixelsPerSecond.dy / (size.height / 2);
    final unitsVelocity = Offset(unitsPerSecondX, unitsPerSecondY);
    final unitVelocityMagnitude = unitsVelocity.distance;

    // 3. Configure SpringDescription using selected ratio
    final spring = SpringDescription.withDampingRatio(
      mass: 1.0,
      stiffness: _selectedPreset.stiffness,
      ratio: _selectedPreset.dampingRatio,
    );

    // 4. Construct SpringSimulation with normalized units
    final simulation = SpringSimulation(
      spring,
      0.0, // Start progress (0.0 = current drag position)
      1.0, // Target progress (1.0 = Alignment.center equilibrium)
      -unitVelocityMagnitude, // Propel in opposing direction of offset
    );

    // 5. Hand simulation directly to AnimationController!
    _physicsController.animateWith(simulation);
  }

  @override
  Widget build(BuildContext context) {
    final size = MediaQuery.sizeOf(context);
    final colorScheme = Theme.of(context).colorScheme;

    return Scaffold(
      appBar: AppBar(
        title: const Text('Physics Simulation & Gestures'),
        centerTitle: true,
      ),
      body: Column(
        children: [
          // Physics Preset Controls
          _buildPresetBar(colorScheme),

          // Telemetry Readout
          _buildTelemetryBar(colorScheme),

          // Interactive Physics Stage
          Expanded(
            child: GestureDetector(
              onPanDown: (details) {
                _physicsController.stop();
                setState(() => _isDragging = true);
              },
              onPanUpdate: (details) {
                setState(() {
                  // Convert drag pixels into Alignment units
                  _dragAlignment += Alignment(
                    details.delta.dx / (size.width / 2),
                    details.delta.dy / (size.height / 2),
                  );
                });
              },
              onPanEnd: (details) {
                setState(() => _isDragging = false);
                _runSpringSimulation(details.velocity.pixelsPerSecond, size);
              },
              child: Stack(
                children: [
                  // Center Target Reticle
                  const Center(
                    child: Icon(
                      Icons.filter_center_focus_rounded,
                      size: 40,
                      color: Colors.black12,
                    ),
                  ),
                  // Spring-Loaded Interactive Card
                  Align(
                    alignment: _dragAlignment,
                    child: _buildSpringCard(colorScheme),
                  ),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildPresetBar(ColorScheme colorScheme) {
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 16.0, vertical: 8.0),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text(
            'Spring Damping Ratio Preset',
            style: TextStyle(fontWeight: FontWeight.bold, fontSize: 13),
          ),
          const SizedBox(height: 6),
          SegmentedButton<SpringPreset>(
            segments: SpringPreset.values
                .map(
                  (preset) => ButtonSegment(
                    value: preset,
                    label: Text(preset.label, style: const TextStyle(fontSize: 11)),
                  ),
                )
                .toList(),
            selected: {_selectedPreset},
            onSelectionChanged: (set) {
              setState(() => _selectedPreset = set.first);
            },
          ),
        ],
      ),
    );
  }

  Widget _buildTelemetryBar(ColorScheme colorScheme) {
    return Container(
      margin: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: colorScheme.surfaceContainerHighest.withValues(alpha: 0.5),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: colorScheme.outlineVariant),
      ),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceAround,
        children: [
          _buildTelemetryMetric(
            'Coordinates (X, Y)',
            '(${_dragAlignment.x.toStringAsFixed(2)}, ${_dragAlignment.y.toStringAsFixed(2)})',
          ),
          _buildTelemetryMetric(
            'Fling Velocity',
            '${_lastVelocity.toInt()} px/s',
          ),
          _buildTelemetryMetric(
            'State',
            _isDragging ? 'DRAGGING' : (_physicsController.isAnimating ? 'SPRINGING' : 'AT REST'),
          ),
        ],
      ),
    );
  }

  Widget _buildTelemetryMetric(String label, String value) {
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        Text(label, style: const TextStyle(fontSize: 10, color: Colors.black54)),
        const SizedBox(height: 2),
        Text(value, style: const TextStyle(fontSize: 12, fontWeight: FontWeight.bold, fontFamily: 'monospace')),
      ],
    );
  }

  Widget _buildSpringCard(ColorScheme colorScheme) {
    return Card(
      elevation: _isDragging ? 12 : 4,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
      color: colorScheme.primaryContainer,
      child: Container(
        width: 160,
        height: 160,
        padding: const EdgeInsets.all(16),
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Icon(Icons.touch_app_rounded, size: 40, color: colorScheme.onPrimaryContainer),
            const SizedBox(height: 8),
            Text(
              'Flick & Release',
              style: TextStyle(
                fontWeight: FontWeight.bold,
                fontSize: 13,
                color: colorScheme.onPrimaryContainer,
              ),
            ),
            const SizedBox(height: 4),
            Text(
              'Drag anywhere & fling',
              style: TextStyle(fontSize: 10, color: colorScheme.onPrimaryContainer.withValues(alpha: 0.7)),
            ),
          ],
        ),
      ),
    );
  }
}
```

### Step-by-Step Code Walkthrough

1. **Touch Interception (`onPanDown`)**:
   When the user places a finger down on the card, `_physicsController.stop()` immediately interrupts any active animation, preventing fighting between touch drag and spring return.
2. **Direct Manipulation (`onPanUpdate`)**:
   `details.delta` offsets are converted into `Alignment` space (-1.0 to 1.0) by dividing by half of the viewport's dimensions (`size.width / 2`). The card tracks the finger at 1:1 parity.
3. **Momentum Extraction (`onPanEnd`)**:
   `details.velocity.pixelsPerSecond` extracts the user's release kinetic energy. Rather than discarding this velocity, `unitsVelocity` maps it to alignment space.
4. **Configuring the `SpringSimulation`**:
   `SpringDescription.withDampingRatio` configures the physical constants. In `_runSpringSimulation`, `SpringSimulation` calculates the trajectory from current offset to `Alignment.center`.
5. **Execution via `animateWith()`**:
   `_physicsController.animateWith(simulation)` hands control to the physics engine. The controller derives its duration dynamically, settling gracefully when kinetic energy dissipates.
